const ClassSensor=require("plcActuator.min.js");class ClassAirAlcoholMQ3 extends ClassSensor{constructor(_opts){super(_opts),this._Name="ClassAirAlcoholMQ3",this._Sensor=require("BaseClassMQX.min.js").connect({dataPin:_opts.pins[0],heatPin:_opts.pins[1],model:"MQ3",r0:_opts.baseline}),this._MinPeriod=250,this._Interval,this._CanRead=!0}Init(){this.Preheat()}Start(_num_channel,_period){let period="number"==typeof _period&_period>=this._MinPeriod?_period:this._MinPeriod;this._Channels[_num_channel].Status=1,this._Interval||(this._Interval=setInterval(()=>{this._Channels[0].Status&&(this._Channels[0].Value=this._CanRead?this._Sensor.read("CH4"):0)},period))}ControlHeater(_val){this._Sensor.heat(_val)}Preheat(){this._CanRead=!1,console.log("Beginning to preheat MQ-3..."),this._Sensor.preheat(()=>{console.log("MQ-3 is heated!"),this._CanRead=!0})}Calibrate(_val){this._Sensor.calibrate(_val)}ChangeFreq(_num_channel,freq){clearInterval(this._Interval),setTimeout(()=>this.Start(freq),this._Minfrequency)}Stop(_num_channel){_num_channel?this._UsedChannels.splice(this._UsedChannels.indexOf(_num_channel)):(this._UsedChannels=[],clearInterval(this._Interval),this._Interval=null)}}exports=ClassAirAlcoholMQ3;